#include <bits/stdc++.h>
using namespace std;

using ll = long long;

const int MAX_N = 7100;
const int MAX_BOARD = 14;
const ll INF = 1e9;

struct Edge {
    int u, v;
    ll f, c;
};

struct DinicMaxFlow {
    int s, t;
    vector<Edge> e;
    vector<int> g[MAX_N];
    int d[MAX_N], p[MAX_N];

    void clear() {
        e.clear();
        for (int i = 0; i < MAX_N; ++i) g[i].clear();
    }

    void add(int u, int v, ll cap) {
        e.push_back({u, v, 0, cap});
        e.push_back({v, u, 0, 0});
        g[u].push_back(e.size() - 2);
        g[v].push_back(e.size() - 1);
    }

    bool bfs() {
        fill(d, d + MAX_N, -1);
        queue<int> q;
        q.push(s);
        d[s] = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int id : g[u]) {
                Edge& ed = e[id];
                if (d[ed.v] == -1 && ed.c > ed.f) {
                    d[ed.v] = d[u] + 1;
                    q.push(ed.v);
                }
            }
        }
        return d[t] != -1;
    }

    ll dfs(int u, ll f) {
        if (u == t || f == 0) return f;
        for (int& i = p[u]; i < (int)g[u].size(); ++i) {
            int id = g[u][i];
            Edge& ed = e[id];
            if (d[ed.v] == d[u] + 1 && ed.c > ed.f) {
                ll pushed = dfs(ed.v, min(f, ed.c - ed.f));
                if (pushed > 0) {
                    ed.f += pushed;
                    e[id ^ 1].f -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    ll maxflow() {
        ll res = 0;
        while (bfs()) {
            fill(p, p + MAX_N, 0);
            while (ll pushed = dfs(s, INF)) {
                res += pushed;
            }
        }
        return res;
    }
};

DinicMaxFlow mf;
char gridA[MAX_BOARD][MAX_BOARD], gridB[MAX_BOARD][MAX_BOARD];
bool mark[MAX_BOARD][MAX_BOARD];
int distMap[MAX_BOARD][MAX_BOARD];
int N, T;
int destNode[103];

int getID(int t, int x, int y) {
    return t * N * N + (x - 1) * N + y;
}

void bfsSearch(int sx, int sy) {
    queue<tuple<int, int, int>> q;
    for (int i = 0; i < MAX_BOARD; ++i)
        for (int j = 0; j < MAX_BOARD; ++j)
            distMap[i][j] = 111;

    distMap[sx][sy] = 0;
    q.emplace(sx, sy, 0);
    int dx[] = {1, 0, 0, -1}, dy[] = {0, 1, -1, 0};

    while (!q.empty()) {
        auto [x, y, d] = q.front(); q.pop();
        if (mark[x][y]) continue;
        mark[x][y] = true;
        distMap[x][y] = d;
        for (int i = 0; i < 4; ++i) {
            int nx = x + dx[i], ny = y + dy[i];
            if (nx < 1 || nx > N || ny < 1 || ny > N || mark[nx][ny] || gridA[nx][ny] == 'Y')
                continue;
            q.emplace(nx, ny, d + 1);
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> T;
    for (int i = 1; i <= N; ++i) cin >> (gridA[i] + 1);
    for (int i = 1; i <= N; ++i) cin >> (gridB[i] + 1);

    mf.clear();
    mf.s = 0;
    mf.t = MAX_N - 2;

    int startX = 0, startY = 0;
    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= N; ++j) {
            if (gridA[i][j] == 'Z') {
                startX = i; startY = j;
                break;
            }
        }
    }

    for (int i = 1; i <= N * N; ++i)
        destNode[i] = MAX_N - 3 - (N * N - i);

    bfsSearch(startX, startY);

    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= N; ++j) {
            if (isdigit(gridA[i][j]))
                mf.add(mf.s, getID(0, i, j), gridA[i][j] - '0');
            if (isdigit(gridB[i][j]))
                mf.add(destNode[getID(0, i, j)], mf.t, gridB[i][j] - '0');
            mf.add(getID(0, i, j), destNode[getID(0, i, j)], INF);
        }
    }

    int dx[] = {1, 0, 0, -1}, dy[] = {0, 1, -1, 0};
    for (int t = 1; t <= T; ++t) {
        for (int i = 1; i <= N; ++i) {
            for (int j = 1; j <= N; ++j) {
                if (gridA[i][j] == 'Y' || gridA[i][j] == 'Z') continue;
                for (int k = 0; k < 4; ++k) {
                    int ni = i + dx[k], nj = j + dy[k];
                    if (ni >= 1 && ni <= N && nj >= 1 && nj <= N &&
                        gridA[ni][nj] != 'Y' && gridA[ni][nj] != 'Z' &&
                        distMap[i][j] >= t && distMap[ni][nj] >= t) {
                        mf.add(getID(t - 1, ni, nj), getID(t, i, j), INF);
                    }
                }
                mf.add(getID(t, i, j), destNode[getID(0, i, j)], INF);
            }
        }
    }

    cout << mf.maxflow() << '\n';
    return 0;
}
